# Calculate rectangle properties for potential transformations

def find_complete_rectangles(grid):
    rows = len(grid)
    cols = len(grid[0])

    def check_rectangle(r1, r2, c1, c2, color):
        # Check top and bottom borders
        for c in range(c1, c2 + 1):
            if grid[r1][c] != color:
                return False
            if grid[r2][c] != color:
                return False
        # Check left and right borders
        for r in range(r1, r2 + 1):
            if grid[r][c1] != color:
                return False
            if grid[r][c2] != color:
                return False
        return True

    rects = []
    colors_to_check = [1, 2, 3, 4, 5, 8]

    for color in colors_to_check:
        for r1 in range(rows):
            for r2 in range(r1 + 1, rows):
                for c1 in range(cols):
                    for c2 in range(c1 + 1, cols):
                        if check_rectangle(r1, r2, c1, c2, color):
                            rects.append((color, r1, r2, c1, c2))

    return rects

